// Function แปลง raw hex string (ไม่มี "0x" นำหน้า) เป็น Bytes — เก็บ byte ทุกตัวที่สมบูรณ์ไว้ตรงๆ
// ตัดทิ้งเฉพาะ nibble สุดท้ายที่ไม่ครบคู่ (กรณี hex ยาวเป็นจำนวนคี่ ตามข้อมูลจริงใน docs/worker.csv)
function hexToBytes(hex: string | null): Uint8Array<ArrayBuffer> | null {
  if (hex === null) {
    return null;
  }

  const pairCount = Math.floor(hex.length / 2);
  const bytes = new Uint8Array(pairCount);

  for (let i = 0; i < pairCount; i += 1) {
    bytes[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }

  // @types/node augments the global Uint8Array to default its ArrayBuffer type parameter to
  // ArrayBufferLike, so a plain `new Uint8Array(n)` no longer structurally matches Prisma's
  // generated Bytes type (Uint8Array<ArrayBuffer>) under this project's TS 6 setup.
  return bytes as Uint8Array<ArrayBuffer>;
}

// Function decode pictureHex แล้วอัปโหลดขึ้น DigitalOcean Spaces ตั้งชื่อไฟล์ตาม laborCode
// (= WorkerCode) กันชนกัน คืน public URL หรือ null ถ้า worker คนนี้ไม่มีรูป
async function uploadWorkerPictureImage(
  laborCode: string,
  pictureHex: string | null
): Promise<string | null> {
  const bytes = hexToBytes(pictureHex);

  if (!bytes) {
    return null;
  }

  return uploadWorkerProfileImage(laborCode, Buffer.from(bytes));
}

// Function seed ข้อมูล master_workers จาก docs/worker.csv (คัดลอกเป็น literal array ด้านบน) ลง DB
export async function seedMasterWorkers(prisma: PrismaClient): Promise<void> {
  const inputs: Prisma.MasterWorkerUpsertArgs[] = await Promise.all(
    masterWorkerSeeds.map(async (worker) => {
      // เก็บ telephone ลง DB เป็นตัวเลขล้วนเสมอ (ตัดขีด/วงเล็บ/เว้นวรรคจาก docs/worker.csv ทิ้ง) ตั้งแต่
      // ตอน seed เลย ไม่ใช่แค่ตอนแปลงเป็น password — กันไม่ให้ค่าที่บันทึกจริงกับ password ไม่ตรงกัน
      const normalizedTelephone = worker.telephone
        ? normalizePhoneDigits(worker.telephone)
        : null;
      const passwordHash = normalizedTelephone
        ? await hashPassword(normalizedTelephone)
        : null;
      const data: Prisma.MasterWorkerUncheckedCreateInput = {
        laborId: worker.laborId,
        laborCode: worker.laborCode,
        prefix: worker.prefix,
        name: worker.name,
        fullName: worker.fullName,
        laborStatus: worker.laborStatus,
        status: worker.status,
        workCode: worker.workCode,
        nationality: worker.laborCountry,
        telephone: normalizedTelephone,
        workStartDate: worker.workStartDate ? new Date(worker.workStartDate) : null,
        laborColor: worker.laborColor,
        laborCoat: worker.laborCoat,
        coatNo: worker.coatNo,
        timeWork: worker.timeWork,
        timeIn: worker.timeIn,
        timeOut: worker.timeOut,
        picture: hexToBytes(worker.pictureHex),
        imageUrl: await uploadWorkerPictureImage(worker.laborCode, worker.pictureHex).catch((error) => {
          console.warn(`[seed] skip image upload for ${worker.laborCode}: ${(error as Error).message}`);
          return null;
        }),
        updateDate: worker.updateDate ? new Date(worker.updateDate) : null,
        source: "master_sync",
        passwordHash,
      };

      return {
        where: { laborId: worker.laborId },
        update: data,
        create: data,
      };
    })
  );

  // timeout สูงกว่าปกติ (default 5s) เพราะแต่ละแถวมี picture เป็น binary หลักหมื่นไบต์ 214 แถวรวมกัน
  // ใช้เวลามากกว่า interactive transaction timeout ปกติของ Prisma
  await prisma.$transaction(
    inputs.map((input) => prisma.masterWorker.upsert(input)),
    { timeout: 60_000 }
  );

  console.log(`Seeded ${masterWorkerSeeds.length} master_workers records (hardcoded from docs/worker.csv).`);
}
